code_actions:
# Calculate 10 * 5
@product = calculator(expression: "10 * 5")

# Add 7 to the result
@sum = calculator(expression: "#{@product} + 7")

# Show the work and final result
final_answer(answer: "10 * 5 = #{@product}, #{@product} + 7 = #{@sum}")

# Perform the multiplication
@calc = calculator(expression: "3 * 4")

# Count words in the sentence
@words = word_counter(text: "The answer is twelve")

# Construct the final answer
final_answer(answer: "3 * 4 = #{@calc}, words: #{@words}")

# Compute 8 * 8
@result1 = calculator(expression: "8 * 8")

# Compute (previous result) / 4
@result2 = calculator(expression: "#{@result1} / 4")

# Return the final result
final_answer(answer: @result2)

# Count words in each string
@result1 = word_counter(text: "hello world")
@result2 = word_counter(text: "foo bar baz")

# Convert results to integers and sum
total = @result1.to_i + @result2.to_i

final_answer(answer: total)
